from pathlib import Path
import datetime,gzip,hashlib,json,shutil
w=Path(__file__).resolve().parent
r=Path('/Users/shawwalters/.codex/worktrees/fees-withdraw-integration/pumpfun-source')
p=r/'research/fees-residual-source-checkpoint-20261027';b=r/'research/fees-residual-parallel-checkpoint-20261027'
sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest()
m=json.loads((p/'archive-manifest.json').read_text()); x=json.loads(gzip.decompress((p/'index.json.gz').read_bytes()))
a=json.loads((p/'base.json').read_text());a.update(restore_combined_sha256=sha(b/'restore_combined.py'),package_sha256=sha(b/'package-sha256.json'));(p/'base.json').write_text(json.dumps(a,indent=2)+'\n')
for name in ['restore_combined.py','test_restore.py']:
 s=(b/name).read_text().replace('fees-work-continuation-20261027','fees-residual-parallel-checkpoint-20261027')
 (p/name).write_text(s)
